        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Flatten grid to find background color (most frequent)
    flat = [cell for row in grid for cell in row]
    bg = Counter(flat).most_common(1)[0][0]

    # Group positions by color (excluding background)
    color_positions = {}
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != bg:
                if val not in color_positions:
