                color_positions[val].append((r, c))

    # Find the rectangle color (solid rectangular block)
    rect_color = None
    rect_bounds = None

    for color, positions in color_positions.items():
        if len(positions) < 2:
            continue

        min_r = min(p[0] for p in positions)
        max_r = max(p[0] for p in positions)
        min_c = min(p[1] for p in positions)
        max_c = max(p[1] for p in positions)

        # Check if it forms a solid rectangle
        expected_count = (max_r - min_r + 1) * (max_c - min_c + 1)
        if len(positions) == expected_count:
            rect_color = color
            rect_bounds = (min_r, max_r, min_c, max_c)
            break

    # If no rectangle found, return original
    if rect_color is None:
        return grid

    min_r, max_r, min_c, max_c = rect_bounds

