            continue

        for r, c in positions:
            # Check horizontal alignment (same row as rectangle)
            if min_r <= r <= max_r:
                if c < min_c:
                    # Marker to the left: draw line rightward to rectangle
                    for cc in range(c, min_c):
                        output[r][cc] = color
                elif c > max_c:
                    # Marker to the right: draw line leftward to rectangle
                    for cc in range(max_c + 1, c + 1):
                        output[r][cc] = color

            # Check vertical alignment (same column as rectangle)
            elif min_c <= c <= max_c:
                if r < min_r:
                    # Marker above: draw line downward to rectangle
                    for rr in range(r, min_r):
                        output[rr][c] = color
                elif r > max_r:
                    # Marker below: draw line upward to rectangle
                    for rr in range(max_r + 1, r + 1):
                        output[rr][c] = color

    return output
